<?php
/*
 * ASTPP post-install hardening - part of astpp-debian13/install.sh
 *
 *  1. Re-encrypts all account passwords from the PUBLIC upstream key
 *     (PRIVATE_KEY in the GitHub repo, identical on every installation) to the
 *     per-installation key generated by the installer.
 *  2. Sets a random password for the "admin" account.
 *  3. Locks the demo accounts shipped in the seed SQL (customer 4727985745 and
 *     provider 3673942894) and gives their SIP devices random passwords - the
 *     upstream SIP password of the demo device is public on GitHub.
 *  4. Stores the new FreeSWITCH event socket password in `freeswich_servers`.
 *  5. Disables the vendor telemetry switch (`datacoll`) in the `system` table.
 *
 * Usage (as root, OPENSSL_CONF must load the legacy provider for Blowfish):
 *   ASTPP_ADMIN_PASSWORD=... ASTPP_ESL_PASSWORD=... php7.4 astpp-postinstall.php
 */

error_reporting(E_ALL);
ini_set('display_errors', 'stderr');

const UPSTREAM_PRIVATE_KEY = '8YSDaBtDHAB3EQkxPAyTz2I5DttzA9uR';
const UPSTREAM_ADMIN_HASH = '8xbJv9wZmjA'; // BF-ECB("admin") with the upstream key
const DEMO_ACCOUNT_NUMBERS = array('4727985745', '3673942894');

function fail($msg)
{
    fwrite(STDERR, "astpp-postinstall: FEHLER: $msg\n");
    exit(1);
}

// Same algorithm as application/libraries/astpp/common.php encode()/decode()
function astpp_encode($value, $key)
{
    $ivSize = openssl_cipher_iv_length('BF-ECB');
    $iv = ($ivSize > 0) ? openssl_random_pseudo_bytes($ivSize) : '';
    $encrypted = openssl_encrypt($value, 'BF-ECB', $key, OPENSSL_RAW_DATA, $iv);
    if ($encrypted === false) {
        fail('openssl_encrypt(BF-ECB) fehlgeschlagen - OpenSSL legacy provider nicht geladen? (OPENSSL_CONF)');
    }
    return str_replace(array('+', '/', '='), array('-', '$', ''), base64_encode($encrypted));
}

function astpp_decode($value, $key)
{
    $data = str_replace(array('-', '$'), array('+', '/'), $value);
    $mod4 = strlen($data) % 4;
    if ($mod4) {
        $data .= substr('====', $mod4);
    }
    $crypttext = base64_decode($data);
    if ($crypttext === false || $crypttext === '') {
        return false;
    }
    $ivSize = openssl_cipher_iv_length('BF-ECB');
    $iv = substr($crypttext, 0, $ivSize);
    return openssl_decrypt(substr($crypttext, $ivSize), 'BF-ECB', $key, OPENSSL_RAW_DATA, $iv);
}

function random_secret($length)
{
    $alphabet = 'ABCDEFGHJKLMNPQRSTUVWXYZabcdefghijkmnopqrstuvwxyz23456789';
    $out = '';
    for ($i = 0; $i < $length; $i++) {
        $out .= $alphabet[random_int(0, strlen($alphabet) - 1)];
    }
    return $out;
}

$cfg = @parse_ini_file('/var/lib/astpp/astpp-config.conf');
if ($cfg === false) {
    fail('/var/lib/astpp/astpp-config.conf nicht lesbar');
}
$new_key = isset($cfg['PRIVATE_KEY']) ? $cfg['PRIVATE_KEY'] : '';
if (strlen($new_key) < 16 || $new_key === UPSTREAM_PRIVATE_KEY) {
    fail('PRIVATE_KEY in astpp-config.conf fehlt oder ist noch der oeffentliche Upstream-Schluessel');
}
$admin_password = (string) getenv('ASTPP_ADMIN_PASSWORD');
$esl_password = (string) getenv('ASTPP_ESL_PASSWORD');
if (strlen($admin_password) < 12 || strlen($esl_password) < 12) {
    fail('ASTPP_ADMIN_PASSWORD / ASTPP_ESL_PASSWORD fehlen');
}

// Self test: Blowfish must work (astpp_encode() aborts otherwise) and should match
// the upstream implementation. On a mismatch the seed passwords cannot be
// re-encrypted - not critical, all seed accounts get new passwords below anyway.
$reencrypt = (astpp_encode('admin', UPSTREAM_PRIVATE_KEY) === UPSTREAM_ADMIN_HASH);
if (! $reencrypt) {
    fwrite(STDERR, "astpp-postinstall: Warnung: Blowfish-Ausgabe weicht vom Upstream-Format ab, Umschluesselung wird uebersprungen\n");
}

mysqli_report(MYSQLI_REPORT_ERROR | MYSQLI_REPORT_STRICT);
try {
    $db = new mysqli($cfg['dbhost'], $cfg['dbuser'], $cfg['dbpass'], $cfg['dbname']);
    $db->set_charset('utf8');
    $db->begin_transaction();

    // 1. re-encrypt all account passwords
    $update = $db->prepare('UPDATE accounts SET password = ? WHERE id = ?');
    $res = $db->query('SELECT id, number, password FROM accounts');
    $converted = 0;
    while ($reencrypt && ($row = $res->fetch_assoc())) {
        if ($row['password'] === '' || $row['password'] === null) {
            continue;
        }
        $plain = astpp_decode($row['password'], UPSTREAM_PRIVATE_KEY);
        if ($plain === false || $plain === '') {
            fwrite(STDERR, "astpp-postinstall: Warnung: Passwort von Konto {$row['number']} nicht entschluesselbar, uebersprungen\n");
            continue;
        }
        $enc = astpp_encode($plain, $new_key);
        $id = (int) $row['id'];
        $update->bind_param('si', $enc, $id);
        $update->execute();
        $converted++;
    }

    // 2. random admin password
    $enc = astpp_encode($admin_password, $new_key);
    $stmt = $db->prepare("UPDATE accounts SET password = ? WHERE number = 'admin' AND type = -1");
    $stmt->bind_param('s', $enc);
    $stmt->execute();
    if ($stmt->affected_rows < 1) {
        // affected_rows is 0 if the value did not change - verify explicitly
        $chk = $db->query("SELECT password FROM accounts WHERE number = 'admin' AND type = -1")->fetch_assoc();
        if (! $chk || $chk['password'] !== $enc) {
            fail('Admin-Konto nicht gefunden');
        }
    }

    // 3. lock demo accounts, random web + SIP passwords
    foreach (DEMO_ACCOUNT_NUMBERS as $number) {
        $enc = astpp_encode(random_secret(24), $new_key);
        $stmt = $db->prepare('UPDATE accounts SET status = 1, password = ? WHERE number = ?');
        $stmt->bind_param('ss', $enc, $number);
        $stmt->execute();

        $acc = $db->prepare('SELECT id FROM accounts WHERE number = ?');
        $acc->bind_param('s', $number);
        $acc->execute();
        $acc_res = $acc->get_result();
        while ($a = $acc_res->fetch_assoc()) {
            $dev = $db->prepare('SELECT id, dir_params FROM sip_devices WHERE accountid = ?');
            $aid = (int) $a['id'];
            $dev->bind_param('i', $aid);
            $dev->execute();
            $dev_res = $dev->get_result();
            while ($d = $dev_res->fetch_assoc()) {
                $params = json_decode($d['dir_params'], true);
                if (! is_array($params)) {
                    $params = array();
                }
                $params['password'] = random_secret(24);
                $params['vm-password'] = (string) random_int(100000, 999999);
                $json = json_encode($params);
                $did = (int) $d['id'];
                $up = $db->prepare('UPDATE sip_devices SET dir_params = ?, status = 1 WHERE id = ?');
                $up->bind_param('si', $json, $did);
                $up->execute();
            }
        }
    }

    // 4. FreeSWITCH event socket password
    $db->query("DELETE FROM freeswich_servers WHERE id <> 1");
    $stmt = $db->prepare("UPDATE freeswich_servers SET freeswitch_host = '127.0.0.1', freeswitch_port = '8021', freeswitch_password = ? WHERE id = 1");
    $stmt->bind_param('s', $esl_password);
    $stmt->execute();

    // 5. vendor telemetry switch off (code path is removed by the patch as well)
    $db->query("UPDATE `system` SET value = '2099-12-31' WHERE name = 'datacoll'");

    $db->commit();
    echo "astpp-postinstall: OK ($converted Passwoerter umgeschluesselt, Admin-Passwort gesetzt, Demo-Konten gesperrt)\n";
} catch (Throwable $e) {
    if (isset($db) && $db instanceof mysqli) {
        @$db->rollback();
    }
    fail($e->getMessage());
}
